<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Pato na Pista</title><script src="https://unpkg.com/vue@3/dist/vue.global.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><style>
*{box-sizing:border-box}body{margin:0;background:#fffaf0;color:#10283d;font:16px system-ui}header{background:#10283d;color:#fff;padding:14px 5vw;font-weight:900}main{max-width:1400px;margin:auto;padding:24px}.hero{display:flex;justify-content:space-between;align-items:center}.hero h1{font-size:clamp(42px,6vw,76px);line-height:.95;letter-spacing:-.06em;margin:8px 0}.panel{background:#fff;border:2px solid #10283d;border-radius:20px;box-shadow:6px 6px #10283d;padding:20px;margin-top:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.full{grid-column:1/-1}textarea{width:100%;min-height:88px;border:2px solid #dbe5e8;border-radius:12px;padding:12px;font:inherit}button{border:2px solid #10283d;border-radius:999px;padding:12px 18px;background:#ffd45c;font-weight:900;cursor:pointer;margin:10px 8px 0 0}.secondary{background:#fff}.participants{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.pill{background:#d8f4f4;border-radius:999px;padding:7px 12px}.qr{display:flex;gap:18px;align-items:center}.qr canvas,.qr img{width:230px!important;height:230px!important;border:10px solid #fff}.fullscreen{position:fixed;inset:0;background:#10283d;color:white;z-index:50;overflow:auto;padding:clamp(18px,3vw,48px)}.race-top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:18px}.race-top h1{font-size:clamp(30px,5vw,70px);line-height:.9;margin:0;letter-spacing:-.06em}.race-stage{max-width:1500px;margin:auto}.stage-track{position:relative;height:clamp(68px,10vh,105px);border-bottom:2px dashed #6fc9d2;display:flex;align-items:center;padding-left:clamp(100px,13vw,220px);overflow:hidden}.stage-track:last-child{border-bottom:0}.stage-track:after{content:'';position:absolute;right:7%;height:100%;border-left:4px solid #ffd45c}.stage-duck{position:absolute;left:3%;z-index:2;text-align:center;font-size:clamp(35px,4vw,60px);--color:#ff7a59;animation:stageRun var(--time) cubic-bezier(.12,.7,.2,1) var(--delay) forwards}.stage-duck .name{display:block;margin-top:-5px;background:var(--color);color:#10283d;font-size:clamp(11px,1.2vw,17px);font-weight:900;padding:4px 10px;border-radius:999px;white-space:nowrap;box-shadow:0 3px 0 rgba(0,0,0,.25)}@keyframes stageRun{0%{left:3%;transform:translateY(0) rotate(-8deg)}25%{transform:translateY(-12px) rotate(7deg)}50%{transform:translateY(3px) rotate(-7deg)}75%{transform:translateY(-9px) rotate(6deg)}100%{left:86%;transform:translateY(0) rotate(0)}}.race-result{max-width:600px;margin:24px auto;background:#fff;color:#10283d;border-radius:18px;padding:18px;text-align:center}.race-result h2{font-size:clamp(28px,4vw,52px);margin:0 0 10px}.race-result ol{text-align:left;margin:0 auto;max-width:330px}.race-result li{padding:7px;border-bottom:1px solid #ddd}.muted{color:#9fc4ce;font-size:14px}@media(max-width:760px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.hero{display:block}.stage-track{padding-left:82px}.stage-duck{font-size:34px}.stage-duck .name{font-size:10px;padding:3px 6px}}
</style></head><body><header>PATO NA PISTA 🦆</header><main id="app"><div v-if="!race" class="hero"><div><small>CORRIDA COM QR CODE</small><h1>Quem cruza a linha primeiro?</h1><p>Crie uma sala e compartilhe o QR code.</p><button @click="createRace">Criar sala</button></div><div style="font-size:90px">🦆</div></div><template v-else><div class="hero"><div><small>SALA @{{ race.code }}</small><h1>Prepare os patos.</h1><p>@{{ race.names.length }} participantes cadastrados.</p></div><div style="font-size:90px">🦆</div></div><section class="panel"><div class="grid"><div class="full"><label>Participantes, um por linha</label><textarea v-model="textNames" @change="importNames"></textarea><div class="participants"><span v-for="name in race.names" class="pill">@{{ name }}</span></div></div><div><button @click="startRace">Começar corrida</button><button class="secondary" @click="openQr">QR em tela cheia</button><button class="secondary" @click="exportCsv">Exportar CSV</button></div><div class="qr"><div id="qrcode"></div><span class="muted">Escaneie para entrar<br>@{{ joinUrl }}</span></div></div></section></template><div v-if="raceScreen" class="fullscreen"><div class="race-stage"><div class="race-top"><div><small>🏁 CORRIDA AO VIVO · SALA @{{ race.code }}</small><h1>@{{ finished?'🏆 Temos um campeão!':'Preparar... apontar... correr!' }}</h1></div><button class="secondary" @click="raceScreen=false">Sair da tela cheia</button></div><div v-for="(name,i) in race.names" class="stage-track"><span class="stage-duck" :style="duckStyle(name,i)">🦆<span class="name">@{{ name }}</span></span></div><div v-if="finished" class="race-result"><h2>🏆 @{{ winner }}</h2><strong>Campeão da corrida!</strong><ol><li v-for="r in race.results">@{{ r.position }}º — @{{ r.name }}</li></ol><button @click="raceScreen=false">Voltar ao painel</button></div></div></div><div v-if="showQr" class="fullscreen" style="background:#fffaf0;color:#10283d;display:grid;place-items:center"><div class="qr"><div><small>ESCANEIE PARA PARTICIPAR</small><h1>Pato na Pista</h1></div><div id="qrcodeFull"></div><button @click="showQr=false">Fechar</button></div></div></main><script>const{createApp}=Vue;createApp({data(){return{race:null,textNames:'',joinUrl:'',poll:null,raceScreen:false,finished:false,showQr:false,order:[],winner:''}},mounted(){const c=location.pathname.split('/').filter(Boolean).pop();if(c&&c!=='')this.load(c)},methods:{async createRace(){this.race=await(await fetch('/api/races',{method:'POST'})).json();this.setup()},async load(c){const r=await fetch('/api/races/'+c);if(r.ok){this.race=await r.json();this.setup()}},setup(){this.textNames=(this.race.names||[]).join('\n');this.joinUrl=location.origin+'/join/'+this.race.code;history.replaceState({},'', '/races/'+this.race.code);setTimeout(()=>new QRCode(document.getElementById('qrcode'),{text:this.joinUrl,width:230,height:230}),50);this.poll=setInterval(async()=>{if(!this.raceScreen){this.race=await(await fetch('/api/races/'+this.race.code)).json();this.textNames=(this.race.names||[]).join('\n')}},2500)},duckStyle(name,i){const rank=this.order.indexOf(name)<0?i:this.order.indexOf(name);const colors=['#ff7a59','#ffd45c','#6ed6c0','#8eb8ff','#f49bd8','#c7a6ff','#f59e72','#8ee0ee'];return{'--color':colors[i%colors.length],'--time':(3.4+rank*.32)+'s','--delay':(Math.random()*.18)+'s'}},openQr(){this.showQr=true;setTimeout(()=>new QRCode(document.getElementById('qrcodeFull'),{text:this.joinUrl,width:520,height:520}),50)},async importNames(){this.race=await(await fetch('/api/races/'+this.race.code+'/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({names:this.textNames.split(/\n|,|;/).map(x=>x.trim()).filter(Boolean)})})).json()},async startRace(){this.raceScreen=true;this.finished=false;const next=await(await fetch('/api/races/'+this.race.code+'/start',{method:'POST'})).json();this.order=next.results.map(r=>r.name);this.winner=this.order[0];setTimeout(()=>{this.race=next;this.finished=true},5800)},exportCsv(){const a=document.createElement('a');a.href='data:text/csv,nome,posicao%0A'+this.race.results.map(r=>r.name+','+r.position).join('%0A');a.download='resultado.csv';a.click()}}}).mount('#app')</script></body></html>
